type step func() step

func done() step { return nil }
func even(n int) step { if n == 0 { return done }; return func() step { return odd(n - 1) } }
func odd(n int) step  { if n == 0 { return done }; return func() step { return even(n - 1) } }

func run(s step) { for s != nil { s = s() } }   // heap frames, one goroutine frame
